import { expect, test } from "vitest";
import { defaultCsvMapping, exportListCsv, parseListCsv, previewListCsv } from "../../src/components/list/individual-list/listCsv";

// Generated by Codex and not thoroughly checked for correctness.
test("an export preserves order, zero, exact seconds, multiline Unicode notes, and blank status when imported", () => {
    const csv = exportListCsv([
        { problemId: "=100A", status: null, helpUsed: "none", timeSpent: 0, notes: '="+試"\r\nNext, line' },
        { problemId: "'100B", status: "solved", solvedOn: "2024-02-29T14:30:00.12Z", timeSpent: 61, notes: "'literal apostrophe" },
        { problemId: "101A" },
    ]);
    expect(csv).toContain("\"'=100A\"");
    expect(csv).toContain("\"'=\"\"+試\"\"");
    const file = parseListCsv("\uFEFF" + csv);
    expect(file.headers).toEqual(["problem_id", "status", "help_used", "solved_on", "time_spent_seconds", "notes"]);
    const { items } = previewListCsv(file, defaultCsvMapping(file.headers), "seconds", new Set());
    expect(items).toEqual([
        { problemId: "=100A", helpUsed: "none", timeSpent: 0, notes: '="+試"\r\nNext, line' },
        { problemId: "'100B", status: "solved", solvedOn: "2024-02-29T14:30:00.12Z", timeSpent: 61, notes: "'literal apostrophe" },
        { problemId: "101A" },
    ]);
});

// Generated by Codex and not thoroughly checked for correctness.
test("legacy exports still restore formula-safe text using their escape column", () => {
    const file = parseListCsv([
        "problem_id,status,help_used,solved_on,time_spent_seconds,notes,cftracker_escaped_text",
        "'=100A,,,,,''literal apostrophe,1",
    ].join("\n"));
    const { items } = previewListCsv(file, defaultCsvMapping(file.headers), "seconds", new Set());
    expect(items).toEqual([{ problemId: "=100A", notes: "'literal apostrophe" }]);
});

// Generated by Codex and not thoroughly checked for correctness.
test("mapped import explains row errors and keeps the first usable occurrence in file order", () => {
    const parsed = parseListCsv([
        "Minutes,ID,Progress,Help,Date,Words",
        "0,known,Solved,None,,",
        "1.5,100A,In progress,Test case,2026-11-22T20:30:00+06:00,'=check invariant",
        "2,100A,Attempted,None,,",
        "0,bad/id,,,,",
        "0,100B,Unknown,,,",
        "0,100C,Solved,Explanation,,",
        "0,100D,Solved,,2026-02-29T20:30:00Z,",
        "0.01,100E,Attempted,,,",
        "0,100F,,,," + "𐐀".repeat(513),
        "0,100G,Solved",
        "",
        "0,101A,,,,",
    ].join("\n"));
    const mapping = { timeSpent: 0, problemId: 1, status: 2, helpUsed: 3, solvedOn: 4, notes: 5 };
    const preview = previewListCsv(parsed, mapping, "minutes", new Set(["known"]));
    expect(preview.items).toEqual([
        { problemId: "100A", status: "in_progress", helpUsed: "test_case", timeSpent: 90, solvedOn: "2026-11-22T14:30:00Z", notes: "'=check invariant" },
        { problemId: "101A", timeSpent: 0 },
    ]);
    expect(preview.rows.map(row => [row.number, row.result])).toEqual([
        [2, "Already in this list."], [3, "Ready"], [4, "Repeated problem ID."],
        [5, "Enter a problem ID of 1–100 characters without slashes or null characters."],
        [6, "Unknown status."], [7, "Unknown help level."], [8, "Enter a valid solve date and time with a timezone (RFC 3339)."],
        [9, "Active time must be between 0 and 2,147,483,647 whole seconds."],
        [10, "Notes must contain at most 512 characters and contain no null characters."],
        [11, "Column count differs from the header."], [13, "Ready"],
    ]);
});

